  DECLARE v_w_050 BIGINT UNSIGNED;
  DECLARE v_w_051 BIGINT UNSIGNED;
  DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; RESIGNAL; END;
  START TRANSACTION;
  DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; RESIGNAL; END;
  START TRANSACTION;
  SELECT COUNT(*),MIN(id) INTO v_count,v_course FROM courses WHERE learning_language='de' AND base_language='fa';
  IF v_count=0 THEN INSERT INTO courses (learning_language,base_language,title,title_translation,description,description_translation,status,metadata) VALUES ('de','fa','Deutsch für Persischsprachige','آلمانی برای فارسی‌زبانان','Independent story-first German course.','دورهٔ مستقل و داستان‌محور زبان آلمانی.','active',JSON_OBJECT('contract','independent_course_v2','storyline','berlin_new_start')); SET v_course=LAST_INSERT_ID(); ELSEIF v_count<>1 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='de-fa course identity is not unique'; END IF;
  SELECT COUNT(*),MIN(id) INTO v_count,v_level FROM levels WHERE course_id=v_course AND cefr_level='A1';
  IF v_count=0 THEN INSERT INTO levels (course_id,cefr_level,title,title_translation,description,description_translation,difficulty_min,difficulty_max,sort_order,status,metadata) VALUES (v_course,'A1','Ankommen und erste Schritte','ورود و نخستین گام‌ها','Absolute-beginner German in a continuous Berlin story.','آلمانی مقدماتی در داستانی پیوسته در برلین.',1,2,1,'active',JSON_OBJECT('seriesStart',1,'seriesEnd',48)); SET v_level=LAST_INSERT_ID(); ELSEIF v_count<>1 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='A1 level identity is not unique'; END IF;
  SELECT COUNT(*),MIN(id) INTO v_count,v_module FROM modules WHERE level_id=v_level AND sort_order=1;
  IF v_count=0 THEN INSERT INTO modules (level_id,title,title_translation,description,description_translation,emoji,difficulty_min,difficulty_max,sort_order,status,metadata) VALUES (v_level,'Neu in Berlin','تازه‌وارد در برلین','Raha arrives, meets local people and handles her first practical needs.','رها وارد برلین می‌شود، با آدم‌های محلی آشنا می‌شود و کارهای نخستین روز را انجام می‌دهد.','🧳',1,2,1,'active',JSON_OBJECT('storylineKey','berlin_new_start')); SET v_module=LAST_INSERT_ID(); ELSEIF v_count<>1 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='A1 module 1 identity is not unique'; END IF;
  SELECT COUNT(*),MIN(id) INTO v_count,v_c_raha FROM characters WHERE course_id=v_course AND name='Raha' AND gender='female';
  IF v_count=0 THEN INSERT INTO characters (course_id,name,gender,voice_key,profile,metadata,is_active) VALUES (v_course,'Raha','female','de_fa_raha',JSON_OBJECT('role','زبان‌آموز و شخصیت اصلی','age_band','adult','locale','Teheran/Berlin'),JSON_OBJECT('storyline','berlin_new_start','independent',TRUE),1); SET v_c_raha=LAST_INSERT_ID(); ELSEIF v_count<>1 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Raha identity is not unique'; END IF;
  SELECT COUNT(*),MIN(id) INTO v_count,v_c_lena FROM characters WHERE course_id=v_course AND name='Lena' AND gender='female';
  IF v_count=0 THEN INSERT INTO characters (course_id,name,gender,voice_key,profile,metadata,is_active) VALUES (v_course,'Lena','female','de_fa_lena',CAST('{"age_band":"adult","locale":"Berlin","role":"دوست محلی رها"}' AS JSON),JSON_OBJECT('storyline','berlin_new_start','independent',TRUE),1); SET v_c_lena=LAST_INSERT_ID(); ELSEIF v_count<>1 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Lena identity is not unique'; END IF;
  SELECT id INTO v_c_raha FROM characters WHERE course_id=v_course AND name='Raha' AND gender='female';
  SELECT id INTO v_c_lena FROM characters WHERE course_id=v_course AND name='Lena' AND gender='female';
  SELECT COUNT(*),MIN(id) INTO v_count,v_chapter FROM chapters WHERE module_id=v_module AND sort_order=1;
  IF v_count=0 THEN
  ELSEIF v_count=1 THEN
    SELECT id INTO v_level FROM levels WHERE course_id=v_course AND cefr_level='A1';
  SELECT id INTO v_module FROM modules WHERE level_id=v_level AND sort_order=1;
  SELECT id INTO v_chapter FROM chapters WHERE module_id=v_module AND sort_order=1;
  IF (SELECT COUNT(*) FROM lessons WHERE chapter_id=v_chapter)<>4 OR (SELECT COUNT(*) FROM turns t JOIN lessons l ON l.id=t.lesson_id WHERE l.chapter_id=v_chapter)<>32 OR (SELECT COUNT(*) FROM activities a JOIN lessons l ON l.id=a.lesson_id WHERE l.chapter_id=v_chapter)<>48 OR JSON_UNQUOTE(JSON_EXTRACT((SELECT metadata FROM chapters WHERE id=v_chapter),'$.stageId'))<>'de-fa-a1-series-0001' THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Existing chapter does not match the validated stage'; END IF;
  ELSE SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Chapter identity is not unique'; END IF;
  IF (SELECT COUNT(*) FROM lessons WHERE chapter_id=v_chapter)<>4 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Chapter must contain exactly four lessons'; END IF;
  IF EXISTS (SELECT 1 FROM lessons l LEFT JOIN turns t ON t.lesson_id=l.id WHERE l.chapter_id=v_chapter GROUP BY l.id HAVING COUNT(t.id)<8 OR COUNT(t.id)>14) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Turn quota failed'; END IF;
  IF EXISTS (SELECT 1 FROM lessons l LEFT JOIN activities a ON a.lesson_id=l.id WHERE l.chapter_id=v_chapter GROUP BY l.id HAVING COUNT(a.id)<12 OR COUNT(a.id)>18) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Activity quota failed'; END IF;
  COMMIT;
END$$
CALL import_nova_series_001()$$
DROP PROCEDURE IF EXISTS import_nova_series_001$$
